    int n = s.length();
    if (n == 0) return true;
    if (n == 1) return true;
    if (n == 2) return wordDict.contains(s);

    boolean[] dp = new boolean[n+1];
    dp[0] = true;
    for (int i = 1; i <= n; i++) {
        for (int j = 0; j < i; j++) {
            if (dp[j] && wordDict.contains(s.substring(j, i))) {
                dp[i] = true;
                break;
            }
        }
    }
    return dp[n];
